import 'dart:io';

import 'package:test/test.dart';
import 'package:zuraffa/src/core/generator_options.dart';
import 'package:zuraffa/src/models/generator_config.dart';
import 'package:zuraffa/src/plugins/datasource/datasource_plugin.dart';

/// Spec #1131 (order 5) — provenance headers on all generated datasource
/// files.
///
/// Every file the datasource plugin freshly emits (interface, remote,
/// local) starts with the `// GENERATED by zfa datasource` provenance
/// header plus a regeneration hint, so `zfa proof check`-style audits and
/// humans can distinguish generated datasources from hand-written ones.
/// Append/merge runs preserve the existing header.
void main() {
  late Directory tempDir;
  late String originalCwd;

  const String headerLine =
      '// GENERATED by zfa datasource — DO NOT EDIT BY HAND.';

  setUp(() async {
    tempDir = await Directory.systemTemp.createTemp('zuraffa_1131_prov_');
    originalCwd = Directory.current.path;
    Directory.current = tempDir.path;
  });

  tearDown(() async {
    Directory.current = originalCwd;
    if (tempDir.existsSync()) {
      await tempDir.delete(recursive: true);
    }
    exitCode = 0;
  });

  Future<List<File>> generateFiles({
    bool local = true,
    bool remote = true,
  }) async {
    final plugin = DataSourcePlugin(
      outputDir: '${tempDir.path}/lib/src',
      options: const GeneratorOptions(),
    );
    final files = await plugin.generate(
      GeneratorConfig(
        name: 'Product',
        outputDir: '${tempDir.path}/lib/src',
        generateDataSource: true,
        generateLocal: local,
        generateRemote: remote,
        methods: const ['get', 'update'],
        force: true,
      ),
    );
    return files.map((f) => File(f.path)).where((f) => f.existsSync()).toList();
  }

  test(
    'every generated datasource file starts with the provenance header',
    () async {
      final files = await generateFiles();
      expect(
        files.length,
        greaterThanOrEqualTo(3),
        reason: 'interface + remote + local expected',
      );

      for (final file in files) {
        final firstLine = file.readAsLinesSync().first;
        expect(
          firstLine,
          headerLine,
          reason: '${file.path} must carry the provenance header',
        );
        // The regeneration hint names the command.
        final secondLine = file.readAsLinesSync()[1];
        expect(
          secondLine,
          startsWith('// Regenerate with: zfa datasource'),
          reason: '${file.path} must carry the regeneration hint',
        );
      }
    },
  );

  test('the header names the entity and the file variant', () async {
    final files = await generateFiles();
    final interface = files.firstWhere(
      (f) => f.path.endsWith('product_datasource.dart'),
    );
    final remote = files.firstWhere(
      (f) => f.path.endsWith('product_remote_datasource.dart'),
    );
    final local = files.firstWhere(
      (f) => f.path.endsWith('product_local_datasource.dart'),
    );

    final interfaceText = interface.readAsStringSync();
    final remoteText = remote.readAsStringSync();
    final localText = local.readAsStringSync();

    expect(interfaceText, contains('Variant: datasource interface.'));
    expect(remoteText, contains('Variant: remote datasource.'));
    expect(localText, contains('Variant: local datasource.'));
    // All name the entity they were generated for.
    expect(interfaceText, contains('Product'));
    expect(remoteText, contains('Product'));
    expect(localText, contains('Product'));
  });

  test(
    'the generated file still parses as valid Dart (header does not break emission)',
    () async {
      final files = await generateFiles();
      for (final file in files) {
        final content = file.readAsStringSync();
        // The emitted library markers + header coexist, and imports follow.
        expect(content, contains('import'));
        expect(content, contains('class '));
      }
    },
  );

  test('append-to-existing preserves the provenance header', () async {
    await generateFiles();
    final interface = File(
      '${tempDir.path}/lib/src/data/datasources/product/product_datasource.dart',
    );
    final headerBefore = interface.readAsLinesSync().first;
    expect(headerBefore, headerLine);

    final plugin = DataSourcePlugin(
      outputDir: '${tempDir.path}/lib/src',
      options: const GeneratorOptions(),
    );
    await plugin.generate(
      GeneratorConfig(
        name: 'Product',
        outputDir: '${tempDir.path}/lib/src',
        generateDataSource: true,
        generateRemote: true,
        methods: const ['getList'],
        appendToExisting: true,
        force: true,
      ),
    );

    expect(
      interface.readAsLinesSync().first,
      headerLine,
      reason: 'an append run must not lose (or bury) the header',
    );
  });
}
